import { spawn } from "node:child_process";
import { createInterface } from "node:readline";
import { CliError } from "./cli/errors.js";
import { describeError, unknownErrorCode } from "./describe-error.js";
const LOG_TAIL_LINES = 5;
export async function openTunnelProcess(input) {
    const { signal, program, installHint } = input;
    if (signal.aborted) {
        throw new CliError(`the tunnel was stopped before ${program} printed a URL.`, {
            code: "aborted",
        });
    }
    const child = (input.spawnImpl ?? spawn)(input.command, input.args, {
        stdio: ["ignore", "pipe", "pipe"],
    });
    const tail = [];
    const logTail = () => (tail.length === 0 ? "" : `\n${tail.join("\n")}`);
    const exited = new Promise((resolveExit) => {
        child.once("error", () => resolveExit(1));
        child.once("close", (code) => resolveExit(code ?? 1));
    });
    return new Promise((resolveTunnel, reject) => {
        let settled = false;
        let opened = false;
        let stopped = false;
        const timeoutMs = input.timeoutMs ?? 30_000;
        const timer = setTimeout(() => {
            fail(new CliError(`${program} printed no tunnel URL within ${timeoutMs}ms.${logTail()}`));
        }, timeoutMs);
        const stop = () => {
            if (settled) {
                child.kill("SIGTERM");
                return;
            }
            fail(new CliError(`the tunnel was stopped before ${program} printed a URL.`, {
                code: "aborted",
            }));
        };
        signal.addEventListener("abort", stop, { once: true });
        void exited.then(() => signal.removeEventListener("abort", stop));
        // The first failure wins, and the open rejects only after the child exits,
        // so a restart never races a live tunnel host for the same tunnel.
        function fail(error) {
            if (settled) {
                return;
            }
            settled = true;
            clearTimeout(timer);
            child.kill("SIGTERM");
            void exited.then(() => reject(error));
        }
        const onLine = (line) => {
            if (stopped) {
                return;
            }
            tail.push(line);
            if (tail.length > LOG_TAIL_LINES) {
                tail.shift();
            }
            let publicUrl;
            try {
                publicUrl = input.parseUrl(line);
            }
            catch (error) {
                if (!(error instanceof CliError)) {
                    throw error;
                }
                stopped = true;
                if (opened) {
                    const hint = error.hint === undefined ? "" : `\n${error.hint}`;
                    (input.warn ?? ((text) => void process.stderr.write(text)))(`${program}: ${error.message}${hint}\n`);
                    child.kill("SIGTERM");
                }
                fail(error);
                return;
            }
            if (publicUrl === undefined || settled) {
                return;
            }
            settled = true;
            opened = true;
            clearTimeout(timer);
            resolveTunnel({ publicUrl, exited });
        };
        // Keep reading after the URL. The process logs until it exits and blocks when a pipe fills.
        for (const stream of [child.stdout, child.stderr]) {
            if (stream !== null) {
                createInterface({ input: stream }).on("line", onLine);
            }
        }
        child.once("error", (error) => {
            fail(unknownErrorCode(error) === "ENOENT"
                ? new CliError(`${program} is not installed (not found on PATH).`, {
                    code: "failed_precondition",
                    hint: installHint,
                })
                : new CliError(`could not start ${program}: ${describeError(error)}`, {
                    hint: installHint,
                }));
        });
        child.once("close", (code) => {
            fail(new CliError(`${program} exited with code ${code ?? "null"} before it printed a tunnel URL.${logTail()}`));
        });
    });
}
